window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ebe0a3a4f5fbac2"]={"versions": [{"id": "FIG-3ebe0a3a4f5fbac2", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>Component Model</code>) zur strukturellen Dekomposition und konzeptionellen Zusammensetzung eines logischen NVRAM-Blocks innerhalb des AUTOSAR Basic Software Moduls NVRAM Manager (NvM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«abstract» NVRAM Block</strong>: Abstrahierte logische Verwaltungseinheit mit dem Attribut <code>- Block Management Type:</code> sowie den formalen Constraints <code>{exact composition depends on Management type}</code> und <code>{handling depends on Block Management Type}</code>.\n</li><li><strong>Teilblöcke (Bestandteile via Komposition):</strong>\n<ul class=\"fig-list\"><li><strong>NV Block</strong>: Physischer nichtflüchtiger Speicherbereich zur Sicherung der Daten.\n</li><li><strong>RAM Block</strong>: Flüchtiger Arbeitsspeicherbereich für den schnellen Zugriff der Applikation zur Laufzeit.\n</li><li><strong>ROM Block</strong>: Optionaler Festwertspeicherbereich mit Default- bzw. Wiederherstellungsdaten.\n</li><li><strong>Administrative Block</strong>: Interner Verwaltungsblock des NvM zur Zustandsverfolgung (z. B. Gültigkeits-, Schreibschutz- und Fehlerstatus).\n</li></ul>\n</li><li><strong>Assoziierte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>«user data» NV Data</strong>: Nutzdatenbereich, der über Kompositionsbeziehungen an <code>NV Block</code>, <code>RAM Block</code> und <code>ROM Block</code> angebunden ist.\n</li><li><strong>Basic Storage Object</strong>: Basiselement der Speicherschicht, das über Realisierungsbeziehungen (<code>«realize»</code>, gestrichelte Pfeile mit geschlossener, nicht ausgefüllter Pfeilspitze) von <code>NV Block</code>, <code>RAM Block</code>, <code>ROM Block</code> und <code>Administrative Block</code> umgesetzt bzw. darauf abgebildet wird.\n</li></ul>\n</li><li><strong>Beziehungsstrukturen:</strong>\n<ul class=\"fig-list\"><li>Vier Kompositionen (ausgefüllte Rauten am <code>NVRAM Block</code>) verbinden den übergeordneten NVRAM-Block mit <code>NV Block</code>, <code>RAM Block</code>, <code>ROM Block</code> und <code>Administrative Block</code>.\n</li><li>Drei Kompositionen (ausgefüllte Rauten an den Blöcken) verbinden <code>NV Block</code>, <code>RAM Block</code> und <code>ROM Block</code> mit <code>«user data» NV Data</code>.\n</li><li>Vier Realisierungspfeile (<code>«realize»</code>) führen von den vier Teilblöcken zu <code>Basic Storage Object</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Klassen- und Komponentenarchitektur dar; dynamische Sequenzabläufe, Aufrufketten oder Zustandsübergänge sind nicht abgebildet. Das Laufzeitverhalten und die konkrete Blockinstanziierung werden über den konfigurierten <code>Block Management Type</code> (z. B. NATIVE, REDUNDANT, DATASET) gesteuert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kompositions-Constraints definieren verbindlich, dass die tatsächliche Existenz und Zusammensetzung von NV-, RAM-, ROM- und Administrative-Blöcken sowie deren Abbildung auf Basic Storage Objects von der spezifischen Block-Management-Konfiguration abhängen. Entwickler und Integratoren müssen beachten, dass der administrative Block stets zur Laufzeitverwaltung vorhanden ist, während ROM- und teilweise NV-Bestandteile je nach Management-Typ und Anwendungsfall variieren. Die Nutzdaten (<code>NV Data</code>) bilden den gemeinsamen fachlichen Kern zwischen RAM-, ROM- und NV-Repräsentation.</p>"}, {"id": "FIG-1c48adedf5be57a8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>Component Model</code>) zur strukturellen Dekomposition und konzeptionellen Zusammensetzung eines logischen NVRAM-Blocks innerhalb des AUTOSAR Basic Software Moduls NVRAM Manager (NvM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«abstract» NVRAM Block</strong>: Abstrahierte logische Verwaltungseinheit mit dem Attribut <code>- Block Management Type:</code> sowie den formalen Constraints <code>{exact composition depends on Management type}</code> und <code>{handling depends on Block Management Type}</code>.\n</li><li><strong>Teilblöcke (Bestandteile via Komposition):</strong>\n<ul class=\"fig-list\"><li><strong>NV Block</strong>: Physischer nichtflüchtiger Speicherbereich zur Sicherung der Daten.\n</li><li><strong>RAM Block</strong>: Flüchtiger Arbeitsspeicherbereich für den schnellen Zugriff der Applikation zur Laufzeit.\n</li><li><strong>ROM Block</strong>: Optionaler Festwertspeicherbereich mit Default- bzw. Wiederherstellungsdaten.\n</li><li><strong>Administrative Block</strong>: Interner Verwaltungsblock des NvM zur Zustandsverfolgung (z. B. Gültigkeits-, Schreibschutz- und Fehlerstatus).\n</li></ul>\n</li><li><strong>Assoziierte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>«user data» NV Data</strong>: Nutzdatenbereich, der über Kompositionsbeziehungen an <code>NV Block</code>, <code>RAM Block</code> und <code>ROM Block</code> angebunden ist.\n</li><li><strong>Basic Storage Object</strong>: Basiselement der Speicherschicht, das über Realisierungsbeziehungen (<code>«realize»</code>, gestrichelte Pfeile mit geschlossener, nicht ausgefüllter Pfeilspitze) von <code>NV Block</code>, <code>RAM Block</code>, <code>ROM Block</code> und <code>Administrative Block</code> umgesetzt bzw. darauf abgebildet wird.\n</li></ul>\n</li><li><strong>Beziehungsstrukturen:</strong>\n<ul class=\"fig-list\"><li>Vier Kompositionen (ausgefüllte Rauten am <code>NVRAM Block</code>) verbinden den übergeordneten NVRAM-Block mit <code>NV Block</code>, <code>RAM Block</code>, <code>ROM Block</code> und <code>Administrative Block</code>.\n</li><li>Drei Kompositionen (ausgefüllte Rauten an den Blöcken) verbinden <code>NV Block</code>, <code>RAM Block</code> und <code>ROM Block</code> mit <code>«user data» NV Data</code>.\n</li><li>Vier Realisierungspfeile (<code>«realize»</code>) führen von den vier Teilblöcken zu <code>Basic Storage Object</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Klassen- und Komponentenarchitektur dar; dynamische Sequenzabläufe, Aufrufketten oder Zustandsübergänge sind nicht abgebildet. Das Laufzeitverhalten und die konkrete Blockinstanziierung werden über den konfigurierten <code>Block Management Type</code> (z. B. NATIVE, REDUNDANT, DATASET) gesteuert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kompositions-Constraints definieren verbindlich, dass die tatsächliche Existenz und Zusammensetzung von NV-, RAM-, ROM- und Administrative-Blöcken sowie deren Abbildung auf Basic Storage Objects von der spezifischen Block-Management-Konfiguration abhängen. Entwickler und Integratoren müssen beachten, dass der administrative Block stets zur Laufzeitverwaltung vorhanden ist, während ROM- und teilweise NV-Bestandteile je nach Management-Typ und Anwendungsfall variieren. Die Nutzdaten (<code>NV Data</code>) bilden den gemeinsamen fachlichen Kern zwischen RAM-, ROM- und NV-Repräsentation.</p>"}], "trans": [{"from": "FIG-3ebe0a3a4f5fbac2", "to": "FIG-1c48adedf5be57a8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
